window.FILM_WORK_PROMPTS={"work_id":"src-48692adb4e7a7e4a","records":[{"work_id":"src-48692adb4e7a7e4a","frame_id":"FG-66c46876fe67f634","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (259).jpg","source_page":"https://film-grab.com/2014/01/04/compliance/","scene":"一只布满皱纹的手紧握着一块橙白相间、带有蓝色线条图案的织物，背景为模糊的深色区域。","analysis":"画面主体为一只紧握的手部特写，占据画面右侧约三分之一区域。手部皮肤纹理清晰，指关节突出，显示出岁月的痕迹。手中紧攥的织物边缘有白色包边，橙色底色上分布着白色不规则色块和蓝色细线。背景处于失焦状态，呈现深灰与暗绿色调，左侧有模糊的浅色垂直结构，整体光线柔和，明暗对比集中在手部与织物上。","prompt":"一只布满皱纹的手部特写，手指紧紧攥着一块折叠的织物。织物呈橙色，上面印有白色不规则几何色块，边缘勾勒着蓝色细线，织物边缘有白色包边。手部皮肤纹理深刻，指甲修剪整齐。背景完全虚化，呈现深灰与暗绿色调，左侧隐约可见模糊的浅色垂直结构。光线柔和自然，主要照亮手部与织物，营造出一种静谧而专注的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T10:17:22-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/07 (259).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.523,"observed_resolution":"normal","observation_limits":[],"id":"VP-01a468dd0bdb3e66","origin":"visual"},{"work_id":"src-48692adb4e7a7e4a","frame_id":"FG-f3ba969bf11b9583","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/19 (263).jpg","source_page":"https://film-grab.com/2014/01/04/compliance/","scene":"一名男子在室内，左手持手机贴耳通话，右手握插有吸管的纸杯，背景为透光的窗帘和墙壁。","analysis":"画面截取人物上半身，人物占据画面左侧及中央大部分区域。背景右侧为大面积明亮的窗帘，形成强烈的逆光效果，使人物面部和身体处于阴影中，轮廓清晰。光线从右后方射入，色调偏暖黄，营造出一种昏暗而私密的室内氛围。","prompt":"一名男子在昏暗的室内，左手举着手机贴在耳边，右手握着一个插有吸管的纸杯。他身穿深色针织开衫，内搭衬衫。背景是明亮的窗户和窗帘，强烈的逆光从右后方射入，使人物面部处于阴影中，仅轮廓被照亮。画面色调偏暖，光影对比强烈，营造出一种沉静、私密的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T10:17:28-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/19 (263).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.504,"observed_resolution":"normal","observation_limits":[],"id":"VP-08b63eccd1f7ca3f","origin":"visual"},{"work_id":"src-48692adb4e7a7e4a","frame_id":"FG-f78af0ae42fe2d06","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/31 (262).jpg","source_page":"https://film-grab.com/2014/01/04/compliance/","scene":"画面主体为一只人类眼睛的极近特写，占据绝大部分视野。可见眼睑、睫毛、虹膜及周围皮肤纹理，背景处于极度虚化状态，无其他环境元素。","analysis":"构图极度紧凑，焦点锁定在眼球中心，周围皮肤纹理清晰可见，包括毛孔与细微皱纹。人物仅可见眼部局部，无其他身体部位。光线柔和偏暖，呈棕褐色调，瞳孔中有微弱反光点。整体明暗对比适中，色彩层次丰富，从深褐到浅棕过渡自然。","prompt":"极近距离拍摄一只人类眼睛，画面几乎被眼球填满。可见灰绿色虹膜、黑色瞳孔及周围棕褐色皮肤，皮肤纹理细腻，有细微皱纹与毛孔。睫毛稀疏，眼睑自然闭合状态。光线从上方柔和照射，形成暖棕色调，瞳孔中有微小高光点。背景完全虚化，呈深褐色模糊色块，无具体物体。整体氛围沉静，色彩饱和度低，质感真实。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T10:17:35-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/31 (262).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.508,"observed_resolution":"normal","observation_limits":[],"id":"VP-613be785d430ed12","origin":"visual"},{"work_id":"src-48692adb4e7a7e4a","frame_id":"FG-9995e78634e6e8ec","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/43 (258).jpg","source_page":"https://film-grab.com/2014/01/04/compliance/","scene":"一名金发年轻女性面部特写，神情紧张地斜视左下方。背景为模糊的棕色纸箱堆叠，环境昏暗压抑，人物占据画面绝大部分。","analysis":"构图极度紧凑，人物面部占据画面中心约80%区域，仅露出额头至下巴及双肩顶部。镜头采用轻微俯视角度，人物视线向左下方偏移。光线昏暗柔和，无强烈高光，肤色呈现低饱和度的冷调，背景纸箱处于焦外虚化状态，明暗对比微弱，整体色调偏灰绿。","prompt":"一名金发年轻女性的面部特写，头发中分略显凌乱，发丝垂在脸颊两侧。她神情紧张，眉头微蹙，眼神锐利地斜视左下方，嘴唇微张。画面仅可见其面部及裸露的双肩顶部，背景是模糊的棕色纸箱堆叠，纸箱边缘隐约可见。整体光线昏暗，色调偏冷灰，无强烈光源，人物面部处于柔和的阴影中，皮肤质感真实，背景虚化严重，营造出压抑、悬疑的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T10:17:42-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/43 (258).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.533,"observed_resolution":"normal","observation_limits":[],"id":"VP-602118018ef50868","origin":"visual"},{"work_id":"src-48692adb4e7a7e4a","frame_id":"FG-557ec90fc20aa06d","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/55 (241).jpg","source_page":"https://film-grab.com/2014/01/04/compliance/","scene":"空旷的停车场，地面有积雪和枯草，几辆汽车停放在远处，路灯杆和光秃的树木散布其间，整体色调灰暗。","analysis":"画面采用俯视视角，构图开阔。前景左侧有一棵枯树，中景处有一辆深色轿车停在车位上，远处还有一辆白色轿车。路灯杆上挂着标有“8D”和“8E”的指示牌。光线平淡，色彩以灰、黑、白为主，呈现出寒冷、空旷的视觉感受。","prompt":"这是一张俯视视角的停车场画面。环境显得寒冷且空旷，地面是深灰色的沥青路面，上面划有白色的停车位线。地面上残留着斑驳的积雪和枯黄的草地。画面中散布着几根黑色的路灯杆，杆上挂着蓝底白字的指示牌，分别写着“8D”和“8E”。几棵光秃秃的树木点缀在停车场中，树枝在灰暗的天空下显得清晰。中景偏右的位置停着一辆深色的轿车，车头朝向左下方。在更远处的左上方，还有一辆白色的轿车。整体光线均匀但阴沉，没有强烈的阴影，色调偏冷，以灰、黑、白为主，营造出一种寂静、萧瑟的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T10:17:50-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/55 (241).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.469,"observed_resolution":"normal","observation_limits":[],"id":"VP-fae5d152b86a9c35","origin":"visual"}]};